def top_k(nums, k):
    order = sorted(range(len(nums)), key=lambda i: (-nums[i], i))
    return [nums[i] for i in order[:k]]

def top_k(nums, k):
    ranked = sorted(enumerate(nums), key=lambda item: (item[1], -item[0]), reverse=True)
    return [value for _, value in ranked[:k]]

def top_k(nums, k):
    pairs = sorted(enumerate(nums), key=lambda p: (p[1], -p[0]), reverse=True)
    return [v for _, v in pairs[:k]]

